<div class="topline"><span><?= e(t('SEE THE WHOLE PICTURE')) ?></span><span><?= e(t('A month of small steps adds up.')) ?></span></div><header class="page-header"><div><h1><?= e(t('Pause. Notice your progress.')) ?></h1><p class="muted"><?= e(t('A monthly view of your money, study, career, habits, and growth.')) ?> <a href="/insights/trends"><?= e(t('Trends & workload')) ?></a></p></div><form class="inline" method="get" action="/insights"><label class="sr-only" for="review-month"><?= e(t('Review month')) ?></label><input id="review-month" type="month" name="month" value="<?= e($month) ?>" required><button class="secondary"><?= e(t('View month')) ?></button></form></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<div class="stats four"><section class="card"><p class="muted"><?= e(t('Income / expenses')) ?></p><div class="big-number"><?= !empty($summary['money']['entries']) ? money($summary['money']['income']) : ui_markup('<span class="no-data">No data yet</span>') ?></div><small><?= !empty($summary['money']['entries']) ? money($summary['money']['expenses']).' spent in '.$month : t('Record your own income and spending') ?></small></section><section class="card"><p class="muted"><?= e(t('Completed study time')) ?></p><div class="big-number"><?= $summary['focus_minutes']>0 ? e($summary['focus_minutes']).' min' : ui_markup('<span class="no-data">No data yet</span>') ?></div><small><?= e(t('Completed focus sessions this month')) ?></small></section><section class="card"><p class="muted"><?= e(t('Assignments due this month')) ?></p><div class="big-number"><?= $summary['assignments']>0 ? e($summary['completed_assignments']).' / '.e($summary['assignments']) : ui_markup('<span class="no-data">No data yet</span>') ?></div><small><?= e(t('Completed / total due')) ?></small></section><section class="card"><p class="muted"><?= e(t('Habit check-ins')) ?></p><div class="big-number"><?= $summary['habit_checkins']>0 ? e($summary['habit_checkins']) : ui_markup('<span class="no-data">No data yet</span>') ?></div><small><?= e(t('Check-ins recorded this month')) ?></small></section></div>
<div class="two-col"><section class="card"><h2><?= e(t('This month, in context')) ?></h2><dl class="summary-list"><dt><?= e(t('Exams scheduled')) ?></dt><dd><?= $summary['exams'] ?: t('No data yet') ?></dd><dt><?= e(t('Applications submitted')) ?></dt><dd><?= $summary['applications'] ?: t('No data yet') ?></dd><dt><?= e(t('Lessons recorded')) ?></dt><dd><?= $summary['lessons'] ?: t('No data yet') ?></dd><dt><?= e(t('Currently active personal goals')) ?></dt><dd><?= $summary['current_goals'] ?: t('No data yet') ?></dd></dl><p class="footnote"><?= e(t('Monthly counts use recorded dates. Active goals are your current goal count, not a historical snapshot.')) ?></p><a class="btn secondary" href="/settings/report" hx-boost="false"><?= e(t('Print / PDF report')) ?></a></section><section class="card"><h2><?= e(t('Your monthly review')) ?></h2><form class="stack" method="post" action="/insights/review"><?= csrf_field() ?><input type="hidden" name="month" value="<?= e($month) ?>"><label><?= e(t('Wins')) ?><textarea name="wins" rows="2" maxlength="5000"><?= e($review['wins'] ?? '') ?></textarea></label><label><?= e(t('Lessons')) ?><textarea name="lessons" rows="2" maxlength="5000"><?= e($review['lessons'] ?? '') ?></textarea></label><label><?= e(t('Next month’s focus')) ?><textarea name="focus" rows="2" maxlength="2000"><?= e($review['focus'] ?? '') ?></textarea></label><label><?= e(t('Month score (1–10)')) ?><input name="score" type="number" min="1" max="10" value="<?= e($review['score'] ?? '') ?>" required></label><button><?= e(t('Save monthly review')) ?></button></form></section></div>
<section class="card" id="alerts"><div class="section-heading"><h2><?= e(t('Things that need your attention')) ?></h2><span class="badge"><?= count($alerts) ?> <?= e(t('reminders')) ?></span></div><?php if (!$alerts): ?><div class="empty"><h3><?= e(t('You’re up to date.')) ?></h3><p><?= e(t('Deadline, payment, goal, and overspending reminders appear here as you add records.')) ?></p></div><?php else: foreach ($alerts as $alert): ?><div class="task-row"><div><a href="<?= e($alert['route']) ?>"><strong><?= e($alert['title']) ?></strong></a><small><?= e($alert['body']) ?></small></div><form method="post" action="/insights/alerts/<?= e($alert['id']) ?>/dismiss"><?= csrf_field() ?><button class="quiet"><?= e(t('Dismiss today')) ?></button></form></div><?php endforeach; endif; ?><h3><?= e(t('Windows notifications')) ?></h3><form method="post" action="/insights/notifications" class="stack"><?= csrf_field() ?><label class="checkbox-label"><input type="checkbox" name="enabled" value="1" <?= Db::setting('notifications_enabled')==='1' ? 'checked' : '' ?>><span><?= e(t('Show Windows reminders while the application is open')) ?></span></label><button class="secondary"><?= e(t('Save preference')) ?></button></form><p class="footnote"><?= e(t('Windows controls notification display and quiet hours. No background service runs after you close the app.')) ?></p></section>
